def process(nifc_areas, state_abbrev) -> pd.DataFrame:
    import geopandas as gpd

    gdf_nifc = gpd.GeoDataFrame(nifc_areas, geometry='geometry')
    gdf_states = gpd.GeoDataFrame(state_abbrev, geometry='geometry')

    results = []
    for idx_nifc, row_nifc in gdf_nifc.iterrows():
        nifc_abbrev = row_nifc['GACCAbbreviation']
        nifc_geom = row_nifc['geometry']

        for idx_state, row_state in gdf_states.iterrows():
            state_abbrev_val = row_state['state_abbrev']
            state_geom = row_state['geometry']

            if nifc_geom.intersects(state_geom):
                results.append({
                    'NIFC_Abbrev': nifc_abbrev,
                    'State_Abbrev': state_abbrev_val
                })

    return pd.DataFrame(results)

def process(nifc_area_state_intersections) -> pd.DataFrame:
    result = nifc_area_state_intersections.drop_duplicates().groupby('NIFC_Abbrev').size().reset_index(name='state_count')
    return result.sort_values('state_count', ascending=False)
